def seed(apps, schema_editor):
    Mission = apps.get_model('missions', 'Mission')
    Question = apps.get_model('missions', 'QuizQuestion')
    for category, entries in BANK.items():
        mission = Mission.objects.filter(category=category, mission_type='quiz', is_active=True).order_by('pk').first()
        if mission is None:
            mission = Mission.objects.create(category=category, mission_type='quiz', title={'observation':'식물 관찰 퀴즈','microbe':'토양과 미생물 퀴즈','local':'지역 환경 퀴즈'}[category], description='분야별 환경 지식을 확인해 보세요.', requires_photo=False)
        for index, (text, correct, wrong1, wrong2, explanation) in enumerate(entries):
            Question.objects.get_or_create(mission=mission, text=text, defaults=dict(order=100+index, choice1=correct, choice2=wrong1, choice3=wrong2, answer=1, explanation=explanation))

class Migration(migrations.Migration):
    dependencies = [('missions', '0011_quizdraw_quizhistory')]
    operations = [migrations.RunPython(seed, migrations.RunPython.noop)]
